134	func TestExecuteExplicitHarnessPinUnknownHarnessFailsWithoutBroaderDispatch(t *testing.T) {
135		svc := publicRouteTraceService(&fakeServiceConfig{
136			providers: map[string]ServiceProviderEntry{
137				"anthropic":  {Type: "anthropic", APIKey: "sk-test"},
138				"openrouter": {Type: "openrouter"},
139			},
140			names:       []string{"anthropic", "openrouter"},
141			defaultName: "anthropic",
142		})
143	
144		ch, err := svc.Execute(context.Background(), ServiceExecuteRequest{
145			Prompt:   "hello",
146			Harness:  "does-not-exist",
147			Provider: "anthropic",
148			Model:    "gpt-5.4",
149		})
150		if err != nil {
151			t.Fatalf("Execute: unexpected synchronous error: %v", err)
152		}
153		final := readFinalEvent(t, ch, 5*time.Second)
154		if final.Status != "failed" {
155			t.Fatalf("final status = %q, want failed", final.Status)
156		}
157		if !strings.Contains(final.Error, "unknown harness") {
158			t.Fatalf("final error = %q, want unknown harness", final.Error)
159		}
160	}
