162	func readFinalEvent(t *testing.T, ch <-chan ServiceEvent, timeout time.Duration) ServiceFinalData {
163		t.Helper()
164		deadline := time.NewTimer(timeout)
165		defer deadline.Stop()
166		for {
167			select {
168			case ev, ok := <-ch:
169				if !ok {
170					t.Fatal("Execute channel closed without final event")
171				}
172				if ev.Type != "final" {
173					continue
174				}
175				var payload ServiceFinalData
176				if err := json.Unmarshal(ev.Data, &payload); err != nil {
177					t.Fatalf("unmarshal final event: %v", err)
178				}
179				return payload
180			case <-deadline.C:
181				t.Fatalf("timed out after %s waiting for final event", timeout)
182				return ServiceFinalData{}
183			}
184		}
185	}
